"""Runtime configuration, loaded once from the environment (and ``.env``).

Every setting has a default that makes the demo runnable with an empty
environment. Secrets stay in the environment and are never logged."""

from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path

try:  # dotenv is a convenience; the app still runs without it.
    from dotenv import load_dotenv

    load_dotenv()
except ImportError:  # pragma: no cover - optional dependency
    pass


def _get(name: str, default: str) -> str:
    value = os.environ.get(name, "").strip()
    return value or default


@dataclass(frozen=True)
class Config:
    """Immutable snapshot of configuration for one process."""

    db_path: Path
    neatlogs_api_key: str
    neatlogs_project: str
    llm_provider: str
    anthropic_api_key: str
    anthropic_model: str
    openai_api_key: str
    openai_model: str
    promotion_clean_runs: int
    l2_auto_refund_ceiling: float
    ledger_repo: Path
    settings_encryption_key: str
    llm_timeout_seconds: float
    llm_max_retries: int

    @property
    def llm_enabled(self) -> bool:
        """True when a real model can be called for planning."""
        if self.llm_provider == "anthropic":
            return bool(self.anthropic_api_key)
        if self.llm_provider == "openai":
            return bool(self.openai_api_key)
        return False

    @property
    def neatlogs_enabled(self) -> bool:
        return bool(self.neatlogs_api_key)


def load_config() -> Config:
    """Build a :class:`Config` from the current environment."""
    return Config(
        db_path=Path(_get("SOLO_LICENSE_DB", "data/solo_license.db")),
        neatlogs_api_key=_get("NEATLOGS_API_KEY", ""),
        neatlogs_project=_get("NEATLOGS_PROJECT", "solo-license"),
        llm_provider=_get("LLM_PROVIDER", "deterministic").lower(),
        anthropic_api_key=_get("ANTHROPIC_API_KEY", ""),
        anthropic_model=_get("ANTHROPIC_MODEL", "claude-sonnet-5-5"),
        openai_api_key=_get("OPENAI_API_KEY", ""),
        openai_model=_get("OPENAI_MODEL", "gpt-4o"),
        promotion_clean_runs=int(_get("PROMOTION_CLEAN_RUNS", "3")),
        l2_auto_refund_ceiling=float(_get("L2_AUTO_REFUND_CEILING", "50")),
        ledger_repo=Path(_get("SOLO_LEDGER_REPO", "data/ledger-repo")),
        settings_encryption_key=_get("SOLO_SETTINGS_ENCRYPTION_KEY", ""),
        llm_timeout_seconds=max(1.0, float(_get("LLM_TIMEOUT_SECONDS", "15"))),
        llm_max_retries=max(0, int(_get("LLM_MAX_RETRIES", "2"))),
    )


_STR_KEYS = (
    "llm_provider", "anthropic_api_key", "anthropic_model",
    "openai_api_key", "openai_model", "neatlogs_api_key", "neatlogs_project",
)


def with_overrides(config: Config, stored: dict[str, str]) -> Config:
    """Overlay operator settings (from the settings table) on env defaults."""
    from dataclasses import replace

    changes: dict[str, object] = {}
    for key in _STR_KEYS:
        if stored.get(key, "").strip():
            changes[key] = stored[key].strip()
    if stored.get("promotion_clean_runs", "").strip():
        changes["promotion_clean_runs"] = max(1, int(stored["promotion_clean_runs"]))
    if stored.get("l2_auto_refund_ceiling", "").strip():
        changes["l2_auto_refund_ceiling"] = max(0.0, float(stored["l2_auto_refund_ceiling"]))
    return replace(config, **changes)
"""Intake agent — turns a free-text customer message into a structured refund
request. With an LLM configured the model does the extraction; without one a
deterministic parser keeps the product fully usable. Either way the result is
only a *request*: what may actually happen is still decided by the license."""

from __future__ import annotations

import json
import re
import sqlite3
from dataclasses import dataclass

from pydantic import BaseModel, Field, ValidationError

from sololicense.config import Config
from sololicense.db.repositories import orders as orders_repo

_ORDER_RE = re.compile(r"\b([A-Z]{2,5}-\d{2,8})\b", re.IGNORECASE)
_MONEY_RE = re.compile(r"(?:\$|usd\s*|rs\.?\s*|₹)\s*(\d+(?:\.\d{1,2})?)", re.IGNORECASE)


@dataclass(frozen=True)
class Intake:
    order_id: str | None
    amount: float | None
    reason: str
    source: str            # deterministic | llm:<model>
    confidence: float = 0.0
    needs_human: bool = False
    note: str = ""


class _LLMIntake(BaseModel):
    order_id: str | None = None
    amount: float | None = Field(default=None, ge=0)
    reason: str = Field(default="customer refund", max_length=140)
    confidence: float = Field(default=0.0, ge=0, le=1)
    needs_human: bool = False


def complete(config: Config, prompt: str, *, max_tokens: int = 300) -> str:
    """One-shot completion against the configured provider. Raises on failure."""
    if config.llm_provider == "anthropic" and config.anthropic_api_key:
        import anthropic

        client = anthropic.Anthropic(
            api_key=config.anthropic_api_key,
            timeout=config.llm_timeout_seconds,
            max_retries=config.llm_max_retries,
        )
        msg = client.messages.create(
            model=config.anthropic_model,
            max_tokens=max_tokens,
            messages=[{"role": "user", "content": prompt}],
        )
        return "".join(b.text for b in msg.content if b.type == "text").strip()
    if config.llm_provider == "openai" and config.openai_api_key:
        import openai

        client = openai.OpenAI(
            api_key=config.openai_api_key,
            timeout=config.llm_timeout_seconds,
            max_retries=config.llm_max_retries,
        )
        resp = client.chat.completions.create(
            model=config.openai_model,
            max_tokens=max_tokens,
            messages=[{"role": "user", "content": prompt}],
        )
        return (resp.choices[0].message.content or "").strip()
    raise RuntimeError("No LLM provider configured.")


def _deterministic(message: str, conn: sqlite3.Connection) -> Intake:
    order = _ORDER_RE.search(message)
    order_id = order.group(1).upper() if order else None
    money = _MONEY_RE.search(message)
    amount = float(money.group(1)) if money else None
    if amount is None and order_id:
        row = orders_repo.get_order(conn, order_id)
        if row is not None:
            amount = float(row["amount"])
    reason = re.sub(r"\s+", " ", message).strip()[:140]
    confidence = 0.85 if order_id and amount is not None else 0.35
    return Intake(
        order_id, amount, reason, "deterministic",
        confidence=confidence,
        needs_human=confidence < 0.5,
    )


def parse_llm_response(text: str, *, model: str) -> Intake | None:
    try:
        data = json.loads(text)
        parsed = _LLMIntake(**data)
    except (TypeError, ValueError, ValidationError):
        return None

    order_id = parsed.order_id.strip().upper() if parsed.order_id else None
    return Intake(
        order_id=order_id or None,
        amount=float(parsed.amount) if parsed.amount is not None else None,
        reason=parsed.reason.strip()[:140] or "customer refund",
        source=f"llm:{model}",
        confidence=float(parsed.confidence),
        needs_human=bool(parsed.needs_human),
    )


def _llm(message: str, config: Config, conn: sqlite3.Connection) -> Intake | None:
    known = ", ".join(r["order_id"] for r in orders_repo.list_orders(conn)[:50])
    prompt = (
        "Extract a refund request from this customer message. Reply with ONLY "
        'JSON: {"order_id": string|null, "amount": number|null, "reason": '
        'string (max 12 words)}. Known order ids: '
        f"{known or 'none'}.\n\nMessage:\n{message}"
    )
    try:
        text = complete(config, prompt, max_tokens=200)
    except Exception:
        return None
    model = (
        config.anthropic_model if config.llm_provider == "anthropic"
        else config.openai_model
    )
    parsed = parse_llm_response(text, model=model)
    if parsed is None:
        return None
    order_id = parsed.order_id
    amount = parsed.amount
    if amount is None and order_id:
        row = orders_repo.get_order(conn, order_id)
        amount = float(row["amount"]) if row is not None else None
    return Intake(
        order_id, amount, parsed.reason, parsed.source,
        confidence=parsed.confidence,
        needs_human=parsed.needs_human or parsed.confidence < 0.5,
    )


def parse_message(message: str, config: Config, conn: sqlite3.Connection) -> Intake:
    if config.llm_enabled:
        parsed = _llm(message, config, conn)
        if parsed is not None:
            return parsed
    return _deterministic(message, conn)
"""Authentication primitives for the HTTP boundary.

Tokens remain deployment secrets. The rest of the application receives only
the authenticated actor identity and role it may safely record in audit data.
"""

from __future__ import annotations

import hmac
import json
from dataclasses import dataclass
from enum import Enum


class Role(str, Enum):
    OPERATOR = "operator"
    APPROVER = "approver"
    ADMIN = "admin"


@dataclass(frozen=True)
class Actor:
    actor_id: str
    role: Role


class TokenAuthenticator:
    """Authenticate bearer tokens configured outside application storage."""

    def __init__(self, actors_by_token: dict[str, Actor]) -> None:
        self._actors_by_token = actors_by_token

    @classmethod
    def from_json(cls, value: str) -> "TokenAuthenticator":
        try:
            raw = json.loads(value)
        except json.JSONDecodeError as error:
            raise ValueError("SOLO_API_TOKENS must be valid JSON.") from error
        if not isinstance(raw, dict) or not raw:
            raise ValueError("SOLO_API_TOKENS must define at least one token.")

        actors: dict[str, Actor] = {}
        for token, details in raw.items():
            if not isinstance(token, str) or not token.strip() or not isinstance(details, dict):
                raise ValueError("Each API token must have an id and role.")
            actor_id = details.get("id")
            role = details.get("role")
            if not isinstance(actor_id, str) or not actor_id.strip():
                raise ValueError("Each API token must have a non-empty id.")
            try:
                actors[token] = Actor(actor_id=actor_id.strip(), role=Role(role))
            except ValueError as error:
                raise ValueError("Each API token role must be operator, approver, or admin.") from error
        return cls(actors)

    def authenticate(self, token: str) -> Actor | None:
        for configured_token, actor in self._actors_by_token.items():
            if hmac.compare_digest(configured_token, token):
                return actor
        return None


def permits(actor: Actor, required: Role) -> bool:
    """Return whether an actor's role includes the requested capability."""
    rank = {Role.OPERATOR: 0, Role.APPROVER: 1, Role.ADMIN: 2}
    return rank[actor.role] >= rank[required]

