    "business_name", "llm_provider",
    *(spec.model_field for spec in PROVIDERS.values() if spec.model_field),
    "compat_base_url",
    "promotion_clean_runs", "l2_auto_refund_ceiling", "l2_auto_credit_ceiling",
    "neatlogs_project", *ECON_KEYS, *SECRET_KEYS,
)
