/* Design tokens — black & white, paper, straight edges.
   No gradients, no border-radius. Status is expressed with fill patterns
   (solid / hatched / outline), not colour. */
:root {
  --paper: #f3f1ec;
  --paper-2: #ebe8e1;
  --sheet: #fbfaf7;
  --ink: #0e0e0d;
  --ink-2: #3a3a37;
  --muted: #76746e;
  --faint: #a9a69e;
  --rule: #0e0e0d;
  --hair: rgba(14, 14, 13, 0.14);
  --signal: #d8341f; /* used only for a live detection, never decoration */

  --font-sans: "Inter Tight", "Helvetica Neue", Arial, sans-serif;
  --font-serif: "Instrument Serif", Georgia, serif;
  --font-mono: "Geist Mono", ui-monospace, monospace;
  --font-hand: "Caveat", "Comic Sans MS", cursive;

  --gutter: clamp(16px, 4vw, 56px);
  --max: 1360px;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}
*, *::before, *::after { box-sizing: border-box; border-radius: 0 !important; }
html, body, #root { margin: 0; min-height: 100%; }
body {
  background: var(--paper);
  color: var(--ink);
  font: 400 15px/1.5 var(--font-sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
a { color: inherit; text-decoration: none; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; background: none; border: 0; padding: 0; }
button:disabled { cursor: not-allowed; opacity: 0.45; }
::selection { background: var(--ink); color: var(--paper); }
:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }
img, svg { display: block; }

/* type */
.serif { font-family: var(--font-serif); font-weight: 400; letter-spacing: -0.01em; }
.italic { font-style: italic; }
.mono { font-family: var(--font-mono); font-size: 11.5px; letter-spacing: 0.04em; text-transform: uppercase; }
.hand { font-family: var(--font-hand); font-weight: 600; letter-spacing: 0; }
.muted { color: var(--muted); }

/* buttons — straight edges, ink fill or outline */
.btn {
  display: inline-flex; align-items: center; gap: 10px;
  height: 44px; padding: 0 20px;
  border: 1px solid var(--ink);
  font-size: 14px; font-weight: 500; letter-spacing: -0.01em;
  transition: background 0.2s var(--ease), color 0.2s var(--ease), transform 0.2s var(--ease);
  white-space: nowrap;
}
.btn:active { transform: translate(1px, 1px); }
.btn-ink { background: var(--ink); color: var(--paper); }
.btn-ink:hover:not(:disabled) { background: var(--paper); color: var(--ink); }
.btn-line { background: transparent; color: var(--ink); }
.btn-line:hover:not(:disabled) { background: var(--ink); color: var(--paper); }
.btn-sm { height: 34px; padding: 0 14px; font-size: 13px; }
.btn-ghost { border-color: transparent; padding: 0 10px; }

