              )}
              <line x1={s.x0} x2={s.x1} y1={s.y} y2={s.y} stroke={s.paused ? 'var(--bad)' : 'var(--ink)'} strokeWidth="2.5" vectorEffect="non-scaling-stroke" />
            </g>
          ))}
        </svg>
      </div>
    </figure>
  );
}

