/* Guided tour spotlight: everything except the step's target is dimmed and
   blurred; a note with an arrow points at what matters right now. */
.sp-pane { position: fixed; z-index: 60; background: rgba(14, 14, 13, 0.42); backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px); transition: all 0.25s var(--ease); }
.sp-ring { position: fixed; z-index: 61; pointer-events: none; outline: 3px solid #f4c430; outline-offset: 0; box-shadow: 0 0 0 6px rgba(244, 196, 48, 0.35); transition: all 0.25s var(--ease); animation: sp-pulse 1.6s ease-in-out infinite; }
@keyframes sp-pulse { 50% { box-shadow: 0 0 0 12px rgba(244, 196, 48, 0.12); } }
.sp-note { position: fixed; z-index: 62; display: grid; gap: 6px; padding: 16px 18px; background: #fff; border: 1px solid var(--ink); box-shadow: 0 10px 30px rgba(14, 14, 13, 0.25); transition: top 0.25s var(--ease), left 0.25s var(--ease); }
.sp-note b { font-size: 17px; font-weight: 600; line-height: 1.3; }
.sp-note p { margin: 0; font-size: 14.5px; line-height: 1.55; color: var(--ink-2); }
.sp-label { font-size: 12px; font-weight: 600; color: var(--wait, #9a6200); text-transform: uppercase; letter-spacing: 0.04em; }
.sp-busy { color: var(--muted) !important; }
.sp-arrow { position: absolute; width: 18px; height: 18px; background: #fff; border: 1px solid var(--ink); transform: rotate(45deg); }
